"""Comprehensive ping test - fixed regex."""
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler
import re

HOSTS = {
    "B1-PC1": {"host": "192.168.122.31", "ip": "10.1.1.10", "guest": False},
    "B1-PC2": {"host": "192.168.122.32", "ip": "10.1.1.11", "guest": False},
